// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        vm.assume(fuzzTimestamp > 0);
        vm.assume(fuzzBlockNumber < type(uint64).max);

        vm.warp(fuzzTimestamp);
        vm.roll(fuzzBlockNumber);

        address caller = address(0xBEEF);
        vm.deal(caller, 30 ether);

        vm.startPrank(caller);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        (bool ok2,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();

        bool atLeastOneFailed = !ok1 || !ok2;
        assertTrue(atLeastOneFailed);
    }
}
